string Dir(string name){var p=Path.Combine(root,name);Directory.CreateDirectory(p);return p;}
var source=Dir("source");Directory.CreateDirectory(Path.Combine(source,"nested","empty"));File.WriteAllText(Path.Combine(source,"nested","niño.txt"),"Contenido con acentos ñ");File.WriteAllBytes(Path.Combine(source,"zero"),[]);
