Assert(a.Status.State=="Completado"&&b.Status.State=="Completado","parallel destinations complete");
Assert(File.ReadAllText(Path.Combine(root,"a","source","nested","niño.txt"))=="Contenido con acentos ñ","unicode content and container structure");
Assert(Directory.Exists(Path.Combine(root,"b","source","nested","empty")),"empty directory preserved");
Assert(new FileInfo(Path.Combine(root,"b","source","zero")).Length==0,"zero-byte file");
var contentPlan=Plan.Create([source],true);var c=Job(contentPlan,Dir("contents"));await c.RunAsync();Assert(File.Exists(Path.Combine(root,"contents","zero"))&&!Directory.Exists(Path.Combine(root,"contents","source")),"contents mode has no extra wrapper");
var target=Path.Combine(root,"contents","nested","niño.txt");File.WriteAllText(target,"existing");var skip=Job(contentPlan,Path.Combine(root,"contents"),Conflict.Skip);await skip.RunAsync();Assert(File.ReadAllText(target)=="existing"&&skip.Status.Skipped==2,"skip policy preserves existing");
var compare=Job(contentPlan,Path.Combine(root,"contents"),Conflict.Compare);await compare.RunAsync();Assert(compare.Status.Copied==1&&compare.Status.Skipped==1,"compare replaces different and skips identical");
bool rejected=false;try{contentPlan.Validate(Path.Combine(source,"child"));}catch(IOException){rejected=true;}Assert(rejected,"reject descendant destination");
rejected=false;try{Plan.Create([source,source+"-missing"],false);}catch(IOException){rejected=true;}Assert(rejected,"missing source rejected");
var cancel=Job(contentPlan,Dir("cancel"));cancel.Cancel();await cancel.RunAsync();Assert(cancel.Status.State=="Cancelado"&&!Directory.EnumerateFiles(Path.Combine(root,"cancel"),"*",SearchOption.AllDirectories).Any(),"cancel before start");
var large=Dir("large");using(var stream=File.Create(Path.Combine(large,"big.bin"))){stream.SetLength(256L*1024*1024);}
var largePlan=Plan.Create([large],true);var paused=Job(largePlan,Dir("paused"));var running=paused.RunAsync();
while(paused.Status.State=="Pendiente")await Task.Delay(1);paused.Pause();await Task.Delay(50);var before=paused.Status.Done;await Task.Delay(100);Assert(paused.Status.State=="Pausado"&&paused.Status.Done==before,"pause stops byte progress");paused.Resume();paused.Cancel();await running;Assert(paused.Status.State=="Cancelado"&&!File.Exists(Path.Combine(root,"paused","big.bin"))&&!Directory.EnumerateFiles(Path.Combine(root,"paused"),"*.partial",SearchOption.AllDirectories).Any(),"cancel removes temporary file");
var changedPlan=Plan.Create([source],true);File.AppendAllText(Path.Combine(source,"nested","niño.txt"),"changed");var changed=Job(changedPlan,Dir("changed"));await changed.RunAsync();Assert(changed.Status.State=="Error","source mutation detected");
var bad=Dir("bad");Directory.CreateDirectory(Path.Combine(bad,"zero"));var badJob=Job(Plan.Create([source],true),bad);var goodJob=Job(Plan.Create([source],true),Dir("good"));await Task.WhenAll(badJob.RunAsync(),goodJob.RunAsync());Assert(badJob.Status.State=="Error"&&goodJob.Status.State=="Completado","one destination failure does not stop another");
Assert(Directory.EnumerateFiles(logs,"*.jsonl").All(p=>File.ReadAllText(p).Contains("action")),"structured logs written");
var sharedPlan=Plan.Create([source],true);var pool=new SourcePool(sharedPlan);
for(int i=0;i<4;i++){var helper=Job(sharedPlan,Dir("helper-"+i));await helper.RunAsync();Assert(await pool.PromoteAsync(helper.Destination),"completed helper promotion "+(i+1));}
var fifth=Job(sharedPlan,Dir("helper-fifth"));await fifth.RunAsync();Assert(!await pool.PromoteAsync(fifth.Destination)&&pool.HelperCount==4,"at most four completed destinations become helpers");
var leases=new List<SourcePool.Lease>();try{for(int i=0;i<4;i++)leases.Add(pool.Acquire(sharedPlan.Files[0],Path.Combine(root,"new-worker")));Assert(leases.Select(l=>l.HelperRoot).Distinct().Count()==4,"concurrent readers spread across four helpers");}finally{foreach(var lease in leases)lease.Dispose();}
var assisted=new CopyJob(sharedPlan,Dir("assisted"),Conflict.Overwrite,true,logs,pool);await assisted.RunAsync();Assert(assisted.Status.State=="Completado"&&File.ReadAllText(assisted.LogPath).Contains("Auxiliar completado"),"copy reads a completed helper without verification");
var invalidRoot=Dir("invalid-helper");var invalidJob=Job(sharedPlan,invalidRoot);await invalidJob.RunAsync();File.AppendAllText(Path.Combine(invalidRoot,sharedPlan.Files[0].Relative),"bad");var auditPool=new SourcePool(sharedPlan);Assert(!await auditPool.PromoteAsync(invalidRoot)&&auditPool.HelperCount==0,"metadata rejects incomplete helper");
var skipRoot=Dir("skipped-helper");var seed=Job(sharedPlan,skipRoot);await seed.RunAsync();var nonempty=sharedPlan.Files.First(f=>f.Size>0);File.WriteAllBytes(Path.Combine(skipRoot,nonempty.Relative),Enumerable.Repeat((byte)88,(int)nonempty.Size).ToArray());var skipBad=Job(sharedPlan,skipRoot,Conflict.Skip);await skipBad.RunAsync();Assert(skipBad.Status.State=="Completado"&&!await new SourcePool(sharedPlan).PromoteAsync(skipRoot),"100 percent with skipped differing files is not an auxiliary source");
var fallbackPool=new SourcePool(sharedPlan);var fallbackRoot=Dir("fallback-helper");var fallbackSeed=Job(sharedPlan,fallbackRoot);await fallbackSeed.RunAsync();await fallbackPool.PromoteAsync(fallbackRoot);File.Delete(Path.Combine(fallbackRoot,nonempty.Relative));var recovered=new CopyJob(sharedPlan,Dir("fallback-output"),Conflict.Overwrite,true,logs,fallbackPool);await recovered.RunAsync();Assert(recovered.Status.State=="Completado"&&File.ReadAllText(recovered.LogPath).Contains("auxiliary-fallback"),"missing helper file falls back to primary without losing bytes");
var lateSource=Dir("late-source");File.WriteAllText(Path.Combine(lateSource,"a.txt"),"Earlier file");File.WriteAllText(Path.Combine(lateSource,"b.txt"),"Current file");File.WriteAllText(Path.Combine(lateSource,"c.txt"),"Later file");var latePlan=Plan.Create([lateSource],true);var catchup=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var lateRoot=Dir("late-output");var lateJob=new CopyJob(latePlan,lateRoot,Conflict.Overwrite,true,logs,null,1,token=>catchup.Task.WaitAsync(token),()=>!catchup.Task.IsCompleted);var lateTask=lateJob.RunAsync();
async Task Until(Func<bool> condition){var deadline=DateTime.UtcNow.AddSeconds(15);while(!condition()){if(DateTime.UtcNow>deadline)throw new Exception("Timed out waiting for copy state");await Task.Delay(5);}}
await Until(()=>File.Exists(Path.Combine(lateRoot,latePlan.Files[^1].Relative))||lateTask.IsCompleted);
Assert(!File.Exists(Path.Combine(lateRoot,latePlan.Files[0].Relative))&&!lateTask.IsCompleted,"late destination copies current tail while earlier files wait");catchup.TrySetResult();await lateTask;Assert(lateJob.Status.State=="Completado"&&latePlan.Files.All(f=>File.ReadAllText(Path.Combine(lateRoot,f.Relative))==File.ReadAllText(f.Source))&&File.ReadAllText(lateJob.LogPath).Contains("catch-up"),"late destination recovers all earlier files after initial group completes");
var batch=new CopyBatch(latePlan,Conflict.Overwrite,true,logs);using(var admission=batch.ReserveAdmission()!){batch.AddDestination(Dir("batch-first"));batch.SealInitial();var wait=batch.WaitAsync();await Until(()=>batch.Jobs.All(j=>j.Status.State=="Completado"));Assert(!wait.IsCompleted,"admission reservation keeps completed initial batch open");batch.AddDestination(Dir("batch-late"),true);admission.Dispose();await wait;Assert(batch.Jobs.Length==2&&batch.Jobs.All(j=>j.Status.State=="Completado")&&!batch.IsOpen,"late device joins without restarting initial copy");}
rejected=false;try{batch.AddDestination(Dir("batch-too-late"),true);}catch(IOException){rejected=true;}Assert(rejected,"closed batch rejects new destinations");
var safe=new FormatSafety("volume-identity","disk-identity",false,false,false,false,false,false,true);
var stoppedBatch=new CopyBatch(latePlan,Conflict.Overwrite,true,logs);using(var hold=stoppedBatch.ReserveAdmission()!){stoppedBatch.AddDestination(Dir("stopped-batch"));stoppedBatch.SealInitial();stoppedBatch.CancelAll();rejected=false;try{stoppedBatch.AddDestination(Dir("stopped-late"),true);}catch(IOException){rejected=true;}Assert(rejected&&stoppedBatch.ReserveAdmission()==null&&!stoppedBatch.IsOpen,"cancel-all stops new admissions as well as active jobs");hold.Dispose();await stoppedBatch.WaitAsync();}
var switchSource=Dir("switch-source");using(var stream=File.Create(Path.Combine(switchSource,"large.bin"))){stream.SetLength(32L*1024*1024);}var switchPlan=Plan.Create([switchSource],true);var donor=Job(switchPlan,Dir("switch-donor"));await donor.RunAsync();var switchPool=new SourcePool(switchPlan);var switching=new CopyJob(switchPlan,Dir("switch-output"),Conflict.Overwrite,true,logs,switchPool,0,null,()=>true);var switchingTask=switching.RunAsync();await Until(()=>switching.Status.Done>=1024*1024||switchingTask.IsCompleted);await switchPool.PromoteAsync(donor.Destination);await switchingTask;var switchLog=File.ReadAllText(switching.LogPath);Assert(switching.Status.State=="Completado"&&switchLog.Contains("Origen principal")&&switchLog.Contains("Auxiliar completado"),"ongoing large file switches from primary to completed auxiliary between segments");
pool.Reject(pool.HelperRoots[0]);Assert(!await pool.PromoteAsync(fifth.Destination),"no fifth promotion after one of the first four helpers is removed");
string simulatedIdentity="volume-A";var identityPool=new SourcePool(latePlan,_=>simulatedIdentity);var identitySeed=Job(latePlan,Dir("identity-helper"));await identitySeed.RunAsync();await identityPool.PromoteAsync(identitySeed.Destination);simulatedIdentity="replacement-volume";using(var lease=identityPool.Acquire(latePlan.Files[0],Path.Combine(root,"identity-target"))){Assert(lease.HelperRoot==null&&identityPool.HelperCount==0,"helper identity replacement is removed before reading and uses primary");}
var corruptPool=new SourcePool(latePlan);var corruptRoot=Dir("corrupt-donor");var corruptSeed=Job(latePlan,corruptRoot);await corruptSeed.RunAsync();await corruptPool.PromoteAsync(corruptRoot);var corruptEntry=latePlan.Files[0];File.WriteAllBytes(Path.Combine(corruptRoot,corruptEntry.Relative),Enumerable.Repeat((byte)90,(int)corruptEntry.Size).ToArray());var preserveRoot=Dir("preserve-existing");File.WriteAllText(Path.Combine(preserveRoot,corruptEntry.Relative),"Existing file must survive");var corruptCopy=new CopyJob(latePlan,preserveRoot,Conflict.Overwrite,false,logs,corruptPool);await corruptCopy.RunAsync();Assert(corruptCopy.Status.State=="Completado"&&corruptPool.HelperCount==0&&File.ReadAllText(Path.Combine(preserveRoot,corruptEntry.Relative))==File.ReadAllText(corruptEntry.Source),"changed helper metadata causes fallback to original without hash verification");
var waitingGate=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var waiting=new CopyJob(latePlan,Dir("late-cancel"),Conflict.Overwrite,true,logs,null,1,t=>waitingGate.Task.WaitAsync(t));var waitingTask=waiting.RunAsync();await Until(()=>waiting.Status.Current.Contains("Esperando")||waitingTask.IsCompleted);waiting.Cancel();await waitingTask;Assert(waiting.Status.State=="Cancelado","late destination can be cancelled while waiting for catch-up");
